oration:none!important;font-weight:700;margin:6px 4px}.editor hr{border:0;border-top:1px solid rgba(86,210,238,.25);margin:22px 0}.editor-source-wrap{display:none}.editor-source-wrap.active{display:block}.editor-preview-modal{display:none;position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.72);padding:24px}.editor-preview-modal.open{display:flex;align-items:center;justify-content:center}.editor-preview-card{width:min(1100px,100%);height:min(90vh,900px);background:#fff;border-radius:16px;overflow:hidden;display:flex;flex-direction:column}.editor-preview-head{height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;background:#071923;color:#eaf8fb}.editor-preview-head button{border:0;background:transparent;color:#fff;font-size:18px;cursor:pointer}.preview-content{flex:1;overflow:auto;padding:30px;color:#14252d;font:16px/1.8 Inter,system-ui,sans-serif}.preview-content img,.preview-content video{max-width:100%;height:auto;border-radius:10px}.preview-content table{width:100%;border-collapse:collapse;margin:18px 0}.preview-content th,.preview-content td{border:1px solid #ccd8dc;padding:9px}.preview-content blockquote{margin:18px 0;padding:12px 16px;border-left:4px solid #20a9c8;background:#eef9fb}.preview-content pre{padding:14px;background:#eef3f5;border-radius:8px;overflow:auto}@media(max-width:800px){.toolbar-group{padding-right:3px}.editor-toolbar{position:sticky;top:0;z-index:4}.editor-toolbar select{min-width:68px}.editor-preview-modal{padding:10px}.editor-preview-card{height:95vh}}@endpush
@push('head')<meta name="csrf-token" content="{{ csrf_token() }}">@endpush
@push('scripts')<script>
const editor=document.getElementById('editor'),source=document.getElementById('content-source'),form=document.getElementById('content-form'),mediaInput=document.getElementById('media-input'),galleryInput=document.getElementById('gallery-input'),videoInput=document.getElementById('video-input'),galleryBatchInput=document.getElementById('gallery-batch-input'),galleryStatus=document.getElementById('gallery-upload-status'),imagePath=document.getElementById('image-path');
function sync(){if(source)source.value=editor.innerHTML}function exec(cmd,value=null){editor.focus();document.execCommand(cmd,false,value);sync()}document.querySelectorAll('.editor-toolbar [data-cmd]').forEach(b=>b.addEventListener('click',()=>exec(b.dataset.cmd,b.dataset.value||null)));
document.getElementById('insert-link').onclick=()=>{const url=prompt('URL');if(url)exec('createLink',url)};
async function upload(file){const fd=new FormData();fd.append('media',file);const res=await fetch('{{ route('admin.site-content.media') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:fd});if(!res.ok)throw new Error('Upload failed for '+file.name);return res.json()}
const safeName=n=>n.replaceAll('"','');
document.getElementById('upload-image').onclick=()=>mediaInput.click();mediaInput.onchange=async()=>{if(!mediaInput.files[0])return;try{const d=await upload(mediaInput.files[0]);exec('insertHTML',`<img src="${d.url}" alt="${safeName(d.name)}" loading="lazy">`)}catch(e){alert(e.message)}mediaInput.value=''};
document.getElementById('upload-video').onclick=()=>videoInput.click();videoInput.onchange=async()=>{if(!videoInput.files[0])return;try{const d=await upload(videoInput.files[0]);exec('insertHTML',`<video controls preload="metadata" src="${d.url}"></video>`)}catch(e){alert(e.message)}videoInput.value=''};
document.getElementById('insert-youtube').onclick=()=>{const url=prompt('YouTube URL');if(!url)return;const m=url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|shorts\/|embed\/))([^?&/]+)/);if(m)exec('insertHTML',`<iframe src="https://www.youtube.com/embed/${m[1]}" title="YouTube" allowfullscreen loading="lazy"></iframe>`)};
document.getElementById('insert-facebook').onclick=()=>{const url=prompt('Facebook video URL');if(url)exec('insertHTML',`<iframe src="https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(url)}&show_text=false" title="Facebook" allowfullscreen loading="lazy"></iframe>`)};
document.getElementById('insert-gallery').onclick=()=>galleryInput.click();galleryInput.onchange=async()=>{const files=[...galleryInput.files];if(!files.length)return;try{const uploads=await Promise.all(files.map(upload));exec('insertHTML','<div class="media-gallery">'+uploads.map(d=>`<img src="${d.url}" alt="${safeName(d.name)}" loading="lazy">`).join('')+'</div>')}catch(e){alert(e.message)}galleryInput.value=''};
if(galleryBatchInput){document.getElementById('gallery-batch-upload').onclick=()=>galleryBatchInput.click();galleryBatchInput.onchange=async()=>{const files=[...galleryBatchInput.files];if(!files.length)return;galleryStatus.textContent=`Uploading ${files.length} media files...`;try{const uploads=await Promise.all(files.map(upload));const html=uploads.map(d=>d.mime.startsWith('video/')?`<video controls preload="metadata" src="${d.url}"></video>`:`<img src="${d.url}" alt="${safeName(d.name)}" loading="lazy">`).join('');exec('insertHTML',`<div class="media-gallery">${html}</div>`);galleryStatus.textContent=`${uploads.length} files added successfully.`}catch(e){galleryStatus.textContent=e.message;alert(e.message)}galleryBatchInput.value=''}}
const coverInput=document.getElementById('cover-input'),coverPreview=document.getElementById('cover-preview'),coverStatus=document.getElementById('cover-status'),removeCover=document.getElementById('remove-cover');
if(coverInput){document.getElementById('cover-upload').onclick=()=>coverInput.click();coverInput.onchange=async()=>{if(!coverInput.files[0])return;coverStatus.textContent='Uploading cover photo...';try{const d=await upload(coverInput.files[0]);imagePath.value=new URL(d.url,window.location.origin).pathname.replace(/^\/storage\//,'');coverPreview.classList.add('has-image');coverPreview.innerHTML=`<img src="${d.url}" alt="Cover preview">`;removeCover.disabled=false;coverStatus.textContent='Cover photo uploaded.'}catch(e){coverStatus.textContent=e.message;alert(e.message)}coverInput.value=''};removeCover.onclick=()=>{imagePath.value='';coverPreview.classList.remove('has-image');coverPreview.innerHTML='<div><i class="fa-regular fa-image"></i><span>No cover photo selected</span></div>';removeCover.disabled=true;coverStatus.textContent='Cover photo removed from this publication.'}}
form.addEventListener('submit',sync);editor.addEventListener('input',sync);sync();

const publicationType=document.getElementById('publication-type');
document.querySelectorAll('[data-publication-type]').forEach(btn=>btn.addEventListener('click',()=>{
    if(!publicationType)return;
    publicationType.value=btn.dataset.publicationType;
    document.querySelectorAll('[data-publication-type]').forEach(b=>b.classList.toggle('selected',b===btn));
}));

const attachmentInput=document.getElementById('attachment-input'),attachmentStatus=document.getElementById('attachment-status'),attachmentProgress=document.getElementById('attachment-progress'),attachmentBar=document.getElementById('attachment-progress-bar'),attachmentCurrent=document.getElementById('attachment-current');
const csrf=document.querySelector('meta[name=csrf-token]')?.content;
const formatSize=b=>{if(!b)return '0 B';const u=['B','KB','MB','GB'];const i=Math.min(Math.floor(Math.log(b)/Math.log(1024)),3);return (b/Math.pow(1024,i)).toFixed(i?1:0)+' '+u[i]};
async function uploadAttachment(file){
    if(!file||file.type!=='application/pdf')throw new Error('Please select a valid PDF file.');
    const max=2*1024*1024*1024;if(file.size>max)throw new Error('The PDF must be 2 GB or smaller.');
    attachmentStatus.textContent='Preparing secure upload...';attachmentProgress.classList.add('show');attachmentBar.style.width='0%';
    const init=await fetch('{{ $item->exists ? route('admin.site-content.attachment.chunks',$item) : '#' }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({filename:file.name,size:file.size})});
    if(!init.ok)throw new Error((await init.json().catch(()=>({}))).message||'Unable to start upload.');
    const meta=await init.json(),id=meta.upload_id,size=meta.chunk_size||524288;let uploaded=0;
    for(let offset=0;offset<file.size;offset+=size){
        const chunk=file.slice(offset,Math.min(offset+size,file.size));
        const res=await fetch('{{ $item->exists ? route('admin.site-content.attachment.chunks',$item) : '#' }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','X-Upload-Id':id,'X-Chunk-Index':String(Math.floor(offset/size)),'X-Chunk-Offset':String(offset),'Content-Type':'application/octet-stream'},body:chunk});
        if(!res.ok)throw new Error((await res.json().catch(()=>({}))).message||'A file chunk failed to upload.');
        uploaded+=chunk.size;attachmentBar.style.width=Math.round(uploaded/file.size*100)+'%';attachmentStatus.textContent='Uploading PDF — '+formatSize(uploaded)+' / '+formatSize(file.size);
    }
    attachmentStatus.textContent='Finalizing PDF...';
    const done=await fetch('{{ $item->exists ? route('admin.site-content.attachment.chunks',$item) : '#' }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','X-Upload-Id':id,'Content-Type':'application/json'},body:JSON.stringify({finalize:true})});
    if(!done.ok)throw new Error((await done.json().catch(()=>({}))).message||'Unable to finalize the PDF.');
    const data=await done.json();
    attachmentStatus.textContent='PDF uploaded successfully.';
    attachmentCurrent.classList.add('has-file');
    attachmentCurrent.innerHTML='<i class="fa-solid fa-file-pdf"></i><div><strong>'+data.name.replaceAll('<','&lt;').replaceAll('>','&gt;')+'</strong><span>'+formatSize(data.size)+'</span></div><button type="button" id="attachment-remove" title="Remove PDF" aria-label="Remove PDF"><i class="fa-solid fa-trash-can"></i></button>';
    bindAttachmentRemove();
}
function bindAttachmentRemove(){
    const btn=document.getElementById('attachment-remove');if(!btn)return;
    btn.onclick=async()=>{if(!confirm('Remove this PDF attachment?'))return;const res=await fetch('{{ $item->exists ? route('admin.site-content.attachment.destroy',$item) : '#' }}',{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});if(!res.ok){attachmentStatus.textContent='Unable to remove the PDF.';return}attachmentCurrent.innerHTML='<div class="attachment-empty"><i class="fa-regular fa-file-pdf"></i><span>No PDF attached</span></div>';attachmentCurrent.classList.remove('has-file');attachmentStatus.textContent='PDF attachment removed.'};
}
if(attachmentInput){document.getElementById('attachment-upload').onclick=()=>attachmentInput.click();attachmentInput.onchange=async()=>{const file=attachmentInput.files[0];if(!file)return;try{await uploadAttachment(file)}catch(e){attachmentStatus.textContent=e.message;attachmentProgress.classList.remove('show');alert(e.message)}attachmentInput.value=''};bindAttachmentRemove();}
const editorShell=editor?.closest('.editor-shell');
const blockFormat=document.getElementById('block-format'),fontSize=document.getElementById('font-size');
const sourceWrap=document.createElement('div');sourceWrap.className='editor-source-wrap';sourceWrap.innerHTML='<textarea class="content-source-editor" id="editor-source-text" spellcheck="false"></textarea>';editor?.parentElement?.appendChild(sourceWrap);
const sourceText=document.getElementById('editor-source-text');let sourceMode=false;
function refreshSource(){if(sourceText)sourceText.value=editor.innerHTML}
function setBlock(tag){if(!tag)return;exec('formatBlock',tag)}
blockFormat?.addEventListener('change',()=>{setBlock(blockFormat.value);blockFormat.value=''});
fontSize?.addEventListener('change',()=>{if(fontSize.value)exec('fontSize',fontSize.value);fontSize.value=''});
document.getElementById('text-color')?.addEventListener('click',()=>{const color=prompt('Text color (example: #0ea5e9)','');if(color)exec('foreColor',color)});
document.getElementById('highlight-color')?.addEventListener('click',()=>{const color=prompt('Highlight color (example: #d9f99d)','');if(color)exec('hiliteColor',color)});
document.getElementById('insert-hr')?.addEventListener('click',()=>exec('insertHTML','<hr>'));
document.getElementById('insert-quote')?.addEventListener('click',()=>exec('insertHTML','<div class="editor-callout"><strong>Key point</strong><br>Write your highlighted message here.</div>'));
document.getElementById('insert-button')?.addEventListener('click',()=>{const label=prompt('Button label','Learn More'),url=prompt('Button URL','https://');if(label&&url)exec('insertHTML','<a class="editor-button" href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>')});
document.getElementById('insert-table')?.addEventListener('click',()=>{const rows=Math.min(10,Math.max(2,parseInt(prompt('Number of rows','3')||'3',10))),cols=Math.min(8,Math.max(1,parseInt(prompt('Number of columns','3')||'3',10)));let html='<table><thead><tr>';for(let i=0;i<cols;i++)html+='<th>Header '+(i+1)+'</th>';html+='</tr></thead><tbody>';for(let r=0;r<rows-1;r++){html+='<tr>';for(let i=0;i<cols;i++)html+='<td>Cell</td>';html+='</tr>'}html+='</tbody></table><p><br></p>';exec('insertHTML',html)});
document.getElementById('editor-source')?.addEventListener('click',()=>{sourceMode=!sourceMode;if(sourceMode){refreshSource();editor.style.display='none';sourceWrap.classList.add('active');document.getElementById('editor-source').classList.add('active')}else{editor.innerHTML=sourceText.value;sourceWrap.classList.remove('active');editor.style.display='';document.getElementById('editor-source').classList.remove('active');sync()}});
document.getElementById('editor-preview')?.addEventListener('click',()=>{if(sourceMode)editor.innerHTML=sourceText.value;const modal=document.getElementById('editor-preview-modal'),preview=document.getElementById('editor-preview-content');preview.innerHTML=editor.innerHTML;modal.classList.add('open');modal.setAttribute('aria-hidden','false')});
document.getElementById('close-editor-preview')?.addEventListener('click',()=>{const modal=document.getElementById('editor-preview-modal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true')});
document.getElementById('editor-preview-modal')?.addEventListener('click',e=>{if(e.target.id==='editor-preview-modal')e.currentTarget.classList.remove('open')});
document.getElementById('editor-fullscreen')?.addEventListener('click',()=>{editorShell?.classList.toggle('fullscreen-shell');document.body.style.overflow=editorShell?.classList.contains('fullscreen-shell')?'hidden':''});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();sync();form?.requestSubmit()}if(e.key==='Escape'&&editorShell?.classList.contains('fullscreen-shell')){editorShell.classList.remove('fullscreen-shell');document.body.style.overflow=''}});
</script>@endpush
